--
-- Table structure for table `snapshots`
--

DROP TABLE IF EXISTS `snapshots`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `snapshots` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `run_id` bigint unsigned NOT NULL,
  `captured_at` datetime NOT NULL,
  `mode` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `section` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `domain` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `column_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `rank_no` smallint unsigned NOT NULL,
  `full_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `stars` int unsigned NOT NULL DEFAULT '0',
  `stars_delta` int NOT NULL DEFAULT '0',
  `lang` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_run_slot` (`run_id`,`section`,`domain`,`column_type`,`rank_no`),
  KEY `idx_run` (`run_id`),
  KEY `idx_proj_time` (`full_name`,`captured_at`),
  KEY `idx_section_time` (`mode`,`section`,`captured_at`),
  KEY `idx_domain` (`domain`,`column_type`,`captured_at`)
) ENGINE=InnoDB AUTO_INCREMENT=17747 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

